import pathlib,tomllib
p=pathlib.Path(r'research/nima/contracts/typed-response.v1.toml')
d=tomllib.loads(p.read_text(encoding='utf-8'))
tables=d['tables']; unions=d['unions']; types=d['types']
assert set(d['root']['required'])==set(d['root']['allowed'])
for name,t in tables.items():
    req=set(t.get('required',[])); allowed=set(t.get('allowed',[]))
    assert req<=allowed,(name,'required-not-allowed',req-allowed)
    assert len(t.get('required',[]))==len(req),(name,'duplicate-required')
    assert len(t.get('allowed',[]))==len(allowed),(name,'duplicate-allowed')
    for f,s in t.get('fields',{}).items():
        assert f in allowed,(name,f,'field-not-allowed')
        if 'schema_ref' in s: assert s['schema_ref'] in tables,(name,f,'missing-table-ref')
        if 'item_schema_ref' in s: assert s['item_schema_ref'] in unions or s['item_schema_ref'] in tables,(name,f,'missing-item-ref')
    for f in t.get('constants',{}):
        assert f in req and f in allowed,(name,f,'constant-not-required')
for name,u in unions.items():
    assert u['discriminator']=='kind'
    assert len(u['variants'])==len(set(u['variants']))
    for v in u['variants']:
        assert v in tables,(name,v,'missing-variant')
        assert tables[v].get('constants',{}).get('kind'),(name,v,'missing-kind-constant')
for name,fs in d['field_sets'].items():
    for field,typ in fs.items(): assert typ in types,(name,field,typ,'missing-type')
ids=[c['id'] for c in d['constraints']]
assert len(ids)==len(set(ids))
assert 'has_attention' not in p.read_text() and 'has_context' not in p.read_text()
assert {'operator','agent'}<=set(d['root']['required'])
print('structure-pass',len(tables),len(unions),len(types),len(ids))
